    #[test]
    #[ignore = "release profile of the INNER JOIN schema check"]
    fn profile_milestone21() {
        let cpu = profile_command("sysctl", &["-n", "machdep.cpu.brand_string"]);
        let mem = profile_command("sysctl", &["-n", "hw.memsize"]);
        let rustc = profile_command("rustc", &["--version"]);
        println!(
            "milestone21 cpu={cpu} mem_bytes={mem} rustc={rustc} value_bytes={} row_vec_bytes={}",
            std::mem::size_of::<Value>(),
            std::mem::size_of::<Vec<Value>>()
        );
        for rows in [100_i64, 1_000, 4_000, 10_000] {
            profile_guard_hash(rows, rows, rows, "equal");
            profile_guard_hash(rows, rows, 10, "duplicates");
            let small = (rows / 100).max(1);
            profile_guard_hash(small, rows, small, "build_outer");
            profile_guard_hash(rows, small, small, "build_inner");
            profile_guard_index(rows, rows, rows, "equal");
            profile_guard_index(rows, rows, 10, "duplicates");
        }
    }

    fn profile_guard_hash(users: i64, orders: i64, user_mod: i64, shape: &str) {
        let mut database = Database::new();
        load_profile_join(&mut database, users, orders, user_mod);
        profile_guard(
            &mut database,
            "HashJoin",
            users,
            orders,
            user_mod,
            shape,
            false,
        );
    }

    fn profile_guard_index(users: i64, orders: i64, user_mod: i64, shape: &str) {
        let dir = crate::test_dir::TestDir::new("profile-m21");
        let path = dir.join("db");
        {
            let mut database = Database::open(&path).unwrap();
            load_profile_join(&mut database, users, orders, user_mod);
        }
        Database::migrate(&path).unwrap();
        let mut database = Database::open(&path).unwrap();
        database
            .execute("CREATE INDEX idx_orders_user ON orders (user_id);")
            .unwrap();
        let _force = ForceIndexJoin::new();
        profile_guard(
            &mut database,
            "IndexNestedLoopJoin",
            users,
            orders,
            user_mod,
            shape,
            true,
        );
    }

    fn profile_guard(
        database: &mut Database,
        strategy: &str,
        users: i64,
        orders: i64,
        user_mod: i64,
        shape: &str,
        index: bool,
    ) {
        let sql = "SELECT u.id, o.amount FROM users u JOIN orders o ON u.id = o.user_id;";
        let explained = query(database, &format!("EXPLAIN {sql}"));
        assert_eq!(
            explained.rows[0][0],
            Value::Text(strategy.to_string()),
            "{shape} users={users} orders={orders}"
        );
        let (expect, hits) = guard_checksum(users, orders, user_mod);
        let (cold, warm, checksum, returned) = time_agg(database, sql);
        assert_eq!(checksum, expect, "{strategy} {shape}");
        assert_eq!(returned, hits);
        let (skip_cold, skip_warm, skip_checksum, _) = {
            let _skip = SkipOnSchemaCheck::new();
            time_agg(database, sql)
        };
        assert_eq!(skip_checksum, expect);
        let build_inner = orders <= users;
        let (groups, positions) = if index {
            (0, 0)
        } else if build_inner {
            let groups = usize::try_from(user_mod.min(users).min(orders)).unwrap_or(usize::MAX);
            (groups, usize::try_from(orders).unwrap_or(usize::MAX))
        } else {
            let groups = usize::try_from(users).unwrap_or(usize::MAX);
            (groups, groups)
        };
        let bytes = if index {
            0
        } else {
            hash_table_bytes(groups, positions)
        };
        let overhead = i128::from(warm as u64) - i128::from(skip_warm as u64);
        println!(
            "milestone21 strategy={strategy} shape={shape} users={users} orders={orders} hits={hits} groups={groups} positions={positions} hash_bytes={bytes} checksum={checksum} check_cold_us={cold} check_warm_us={warm} skip_cold_us={skip_cold} skip_warm_us={skip_warm} overhead_us={overhead}"
        );
    }

    fn guard_checksum(users: i64, orders: i64, user_mod: i64) -> (i64, usize) {
        let mut checksum = 0_i64;
        let mut hits = 0_usize;
        for id in 0..orders {
            let user = id % user_mod;
            if user >= users {
                continue;
            }
            hits += 1;
            checksum = checksum.wrapping_add(user);
            if id % 2 == 1 {
                checksum = checksum.wrapping_add(id % 5);
            }
        }
        (checksum, hits)
    }

    #[test]
    fn left_distinct_aggregates_match_nested_and_a_collision() {
        let mut db = Database::new();
        db.execute("CREATE TABLE users (id INT, name TEXT);")
            .unwrap();
        db.execute("CREATE TABLE orders (user_id INT, amount INT);")
            .unwrap();
        db.execute("INSERT INTO users VALUES (1, 'Ada'), (2, 'Ada'), (3, 'Bea'), (NULL, 'Dee');")
            .unwrap();
        db.execute("INSERT INTO orders VALUES (1, 10), (1, 10), (1, 20), (3, 10), (NULL, 5);")
            .unwrap();
        let sqls = [
            "SELECT COUNT(*), COUNT(o.amount), COUNT(DISTINCT o.amount), SUM(o.amount), SUM(DISTINCT o.amount), AVG(o.amount), AVG(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id;",
            "SELECT u.name, COUNT(*), COUNT(DISTINCT o.amount), SUM(DISTINCT o.amount), AVG(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id GROUP BY u.name;",
            "SELECT u.name, COUNT(DISTINCT o.user_id) AS n FROM users u LEFT JOIN orders o ON o.user_id = u.id GROUP BY u.name HAVING n > 0 ORDER BY n DESC;",
            "SELECT COUNT(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id AND o.amount > 15;",
            "SELECT COUNT(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id OR o.amount = 5;",
            "SELECT COUNT(*), COUNT(DISTINCT b.name) FROM users a LEFT JOIN users b ON a.id = b.id;",
            "SELECT COUNT(*), COUNT(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id AND FALSE;",
            "SELECT COUNT(*), COUNT(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id AND NULL;",
            "SELECT COUNT(*), COUNT(DISTINCT b.name) FROM users a LEFT JOIN users b ON a.name = b.name;",
        ];
        let nested = {
            let _force = ForceNestedJoin::new();
            sqls.iter()
                .map(|sql| query(&mut db, sql).rows)
                .collect::<Vec<_>>()
        };
        let hashed = sqls
            .iter()
            .map(|sql| query(&mut db, sql).rows)
            .collect::<Vec<_>>();
        assert_eq!(hashed, nested);
        let collided = {
            let _force = ForceHashCollision::new();
            sqls.iter()
                .map(|sql| query(&mut db, sql).rows)
                .collect::<Vec<_>>()
        };
        assert_eq!(collided, nested);
        assert_eq!(
            nested[0],
            vec![vec![
                Value::Integer(6),
                Value::Integer(4),
                Value::Integer(2),
                Value::Integer(50),
                Value::Integer(30),
                Value::Ratio {
                    numerator: 25,
                    denominator: 2,
                },
                Value::Ratio {
                    numerator: 15,
                    denominator: 1,
                },
            ]]
        );
        assert_eq!(nested[6], vec![vec![Value::Integer(4), Value::Integer(0)]]);
        assert_eq!(nested[7], vec![vec![Value::Integer(4), Value::Integer(0)]]);
        assert_eq!(nested[8], vec![vec![Value::Integer(6), Value::Integer(3)]]);
    }

    #[test]
    fn a_later_left_distinct_overflow_is_not_hidden_by_limit() {
        let mut db = Database::new();
        db.execute("CREATE TABLE users (id INT, name TEXT);")
            .unwrap();
        db.execute("CREATE TABLE orders (user_id INT, amount INT);")
            .unwrap();
        db.execute("INSERT INTO users VALUES (1, 'Ada'), (2, 'Bea');")
            .unwrap();
        db.execute("INSERT INTO orders VALUES (1, 10), (2, 9223372036854775807), (2, 1);")
            .unwrap();
        let error = db
            .execute(
                "SELECT u.name, SUM(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id GROUP BY u.name ORDER BY u.name ASC LIMIT 1;",
            )
            .unwrap_err();
        assert_eq!(error.to_string(), "SUM overflows INTEGER");
        assert_eq!(
            query(
                &mut db,
                "SELECT COUNT(*) FROM users u LEFT JOIN orders o ON u.id = o.user_id;",
            )
            .rows,
            vec![vec![Value::Integer(3)]]
        );
        {
            let _budget = DistinctReserveBudget::limit(0);
            let error = db
                .execute(
                    "SELECT COUNT(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id;",
                )
                .unwrap_err();
            assert!(
                error.to_string().contains("DISTINCT set is too large"),
                "{error}"
            );
        }
        assert_eq!(
            query(
                &mut db,
                "SELECT COUNT(DISTINCT o.amount) FROM users u LEFT JOIN orders o ON u.id = o.user_id;",
            )
            .rows,
            vec![vec![Value::Integer(3)]]
        );
    }

