    #[test]
    #[ignore = "release profile of bulk B+ tree deletion"]
    fn profile_milestone31() {
        let cpu = profile_command("sysctl", &["-n", "machdep.cpu.brand_string"]);
        let mem = profile_command("sysctl", &["-n", "hw.memsize"]);
        let rustc = profile_command("rustc", &["--version"]);
        println!("milestone31 cpu={cpu} mem_bytes={mem} rustc={rustc}");
        let _phases = crate::storage::enable_phases();
        for rows in [100_i64, 1_000, 10_000, 100_000] {
            let (_base_dir, base) = seed_delete_db("m31-base", rows, 0x3100);
            let samples = if rows == 100_000 { 3 } else { 1 };
            for workload in [
                "one",
                "sparse",
                "duplicates",
                "half",
                "all",
                "alternating",
                "consecutive",
                "wide",
            ] {
                let mut taken = Vec::with_capacity(samples);
                for sample in 0..samples {
                    taken.push(profile_bulk_delete(
                        &base,
                        rows,
                        workload,
                        sample,
                        VerifyMode::Descent,
                    ));
                }
                if samples > 1 {
                    for sample in &taken[1..] {
                        assert_eq!(sample.bulk_wal, taken[0].bulk_wal, "{workload}");
                        assert_eq!(sample.spans, taken[0].spans, "{workload}");
                        assert_eq!(sample.checksum, taken[0].checksum, "{workload}");
                        assert_eq!(sample.id_height, taken[0].id_height, "{workload}");
                        assert_eq!(sample.id_pages, taken[0].id_pages, "{workload}");
                    }
                    let median_us = median(
                        &taken
                            .iter()
                            .map(|sample| sample.bulk_us)
                            .collect::<Vec<_>>(),
                    );
                    let grouped_us = median(
                        &taken
                            .iter()
                            .map(|sample| sample.grouped_us)
                            .collect::<Vec<_>>(),
                    );
                    let bulk_index = median(
                        &taken
                            .iter()
                            .map(|sample| sample.bulk_index_us)
                            .collect::<Vec<_>>(),
                    );
                    let grouped_index = median(
                        &taken
                            .iter()
                            .map(|sample| sample.grouped_index_us)
                            .collect::<Vec<_>>(),
                    );
                    println!(
                        "milestone31 median workload={workload} rows={rows} samples={samples} bulk_us={median_us} grouped_us={grouped_us} bulk_index_us={bulk_index} grouped_index_us={grouped_index} bulk_wal={} grouped_wal={} spans={} merges={} internal_merges={} contractions={} allocated={} freed={} scratch={} singles={} grouped_singles={} descents={} id_height={} id_pages={} checksum={}",
                        taken[0].bulk_wal,
                        taken[0].grouped_wal,
                        taken[0].spans,
                        taken[0].merges,
                        taken[0].internal_merges,
                        taken[0].contractions,
                        taken[0].allocated,
                        taken[0].freed,
                        taken[0].scratch,
                        taken[0].singles,
                        taken[0].grouped_singles,
                        taken[0].descents,
                        taken[0].id_height,
                        taken[0].id_pages,
                        taken[0].checksum
                    );
                }
            }
        }
    }

    struct BulkSample {
        bulk_us: u128,
        grouped_us: u128,
        bulk_index_us: u128,
        grouped_index_us: u128,
        bulk_wal: u64,
        grouped_wal: u64,
        spans: u64,
        merges: u64,
        internal_merges: u64,
        contractions: u64,
        allocated: u64,
        freed: u64,
        scratch: u64,
        singles: u64,
        grouped_singles: u64,
        descents: u64,
        leaf_decodes: u64,
        sibling_steps: u64,
        posting_compares: u64,
        duplicate_checks: u64,
        ordered_verified: u64,
        fallback_verified: u64,
        presence_verified: u64,
        presence_builds: u64,
        map_bytes: u64,
        map_hits: u64,
        map_misses: u64,
        presence_build_us: u128,
        presence_member_us: u128,
        early_plans: u64,
        estimated_pages: u64,
        scanned_pages: u64,
        validations_skipped: u64,
        tree_validations: u64,
        path_us: u128,
        reused_paths: u64,
        path_invalidations: u64,
        ancestor_reads: u64,
        ancestor_writes: u64,
        separator_updates: u64,
        index_pages: u32,
        grouped_postings: u64,
        id_height: u32,
        id_pages: usize,
        checksum: i64,
    }

    #[derive(Clone, Copy, PartialEq, Eq)]
    enum VerifyMode {
        Presence,
        Late,
        Chain,
        Descent,
        Prior,
        Seal,
    }

    fn profile_bulk_delete(
        base: &std::path::Path,
        rows: i64,
        workload: &str,
        sample: usize,
        mode: VerifyMode,
    ) -> BulkSample {
        let sql = match workload {
            "one" => "DELETE FROM users WHERE id = 1;".to_string(),
            "ten" => "DELETE FROM users WHERE id >= 1 AND id <= 10;".to_string(),
            "buckets" => "DELETE FROM users WHERE bucket = 0 OR bucket = 1;".to_string(),
            "sparse" => "DELETE FROM users WHERE bucket IS NULL;".to_string(),
            "duplicates" => "DELETE FROM users WHERE bucket = 1;".to_string(),
            "half" => format!("DELETE FROM users WHERE id < {};", rows / 2),
            "all" => "DELETE FROM users WHERE TRUE OR id = 0;".to_string(),
            "alternating" => "DELETE FROM users WHERE active = TRUE;".to_string(),
            "consecutive" => format!(
                "DELETE FROM users WHERE id >= 1 AND id < {};",
                (rows / 4).max(1)
            ),
            "wide" => format!("DELETE FROM users WHERE name = '{}';", "w".repeat(80)),
            _ => unreachable!(),
        };
        let (_bulk_dir, mut bulk) = {
            let (dir, _path, db) = open_copy(base, "m31-bulk");
            (dir, db)
        };
        let (_grouped_dir, mut grouped) = {
            let (dir, _path, db) = open_copy(base, "m31-grouped");
            (dir, db)
        };
        crate::storage::reset_phases();
        let started = std::time::Instant::now();
        let bulk_count = match mode {
            VerifyMode::Descent => {
                let _guard = crate::storage::ForceDescentVerify::new();
                change_count(&mut bulk, &sql)
            }
            VerifyMode::Chain => {
                let _guard = crate::storage::ForceChainVerify::new();
                change_count(&mut bulk, &sql)
            }
            VerifyMode::Presence => change_count(&mut bulk, &sql),
            VerifyMode::Late => {
                let _guard = crate::storage::ForceLatePresence::new();
                change_count(&mut bulk, &sql)
            }
            VerifyMode::Prior => {
                let _guard = crate::storage::ForcePriorPlan::new();
                change_count(&mut bulk, &sql)
            }
            VerifyMode::Seal => {
                let _guard = crate::storage::ForceAncestorRewrite::new();
                change_count(&mut bulk, &sql)
            }
        };
        let bulk_us = started.elapsed().as_micros();
        let bulk_phases = crate::storage::take_phases();
        crate::storage::reset_phases();
        let started = std::time::Instant::now();
        let grouped_count = {
            let _guard = crate::storage::ForceGroupedDelete::new();
            change_count(&mut grouped, &sql)
        };
        let grouped_us = started.elapsed().as_micros();
        let grouped_phases = crate::storage::take_phases();
        assert_eq!(bulk_count, grouped_count, "{workload} {rows}");
        assert_eq!(
            mutation_checksum(&mut bulk),
            mutation_checksum(&mut grouped),
            "{workload} {rows}"
        );
        assert_eq!(
            bulk.table("users").unwrap().next_row_id(),
            grouped.table("users").unwrap().next_row_id(),
            "{workload} {rows}"
        );
        let (id_height, id_pages) = bulk.index_shape("idx_users_id").unwrap();
        let (bucket_height, bucket_pages) = bulk.index_shape("idx_users_bucket").unwrap();
        let (old_id_height, old_id_pages) = grouped.index_shape("idx_users_id").unwrap();
        if workload == "one" {
            assert_eq!(bulk_phases.bulk_spans, 0, "{rows}");
            assert_eq!(bulk_phases.leaf_redistributions, 0, "{rows}");
            assert_eq!(
                bulk_phases.index_singles, grouped_phases.index_singles,
                "{rows}"
            );
        }
        if rows >= 1_000 && matches!(workload, "half" | "all" | "consecutive" | "alternating") {
            assert!(
                bulk_phases.bulk_spans > 0,
                "{workload} {rows} spans {}",
                bulk_phases.bulk_spans
            );
            assert!(
                bulk_phases.index_singles < grouped_phases.index_singles,
                "{workload} {rows} bulk singles {} grouped singles {}",
                bulk_phases.index_singles,
                grouped_phases.index_singles
            );
        }
        let checksum = mutation_checksum(&mut bulk);
        println!(
            "milestone31 workload={workload} rows={rows} sample={sample} count={bulk_count} bulk_us={bulk_us} grouped_us={grouped_us} bulk_heap_us={} grouped_heap_us={} bulk_index_us={} grouped_index_us={} bulk_wal={} grouped_wal={} bulk_frames={} grouped_frames={} descents={} grouped_descents={} redistributions={} leaf_merges={} internal_merges={} contractions={} allocated={} freed={} scratch={} singles={} grouped_singles={} batches={} id_height={id_height} id_pages={id_pages} old_id_height={old_id_height} old_id_pages={old_id_pages} bucket_height={bucket_height} bucket_pages={bucket_pages} checksum={checksum}",
            bulk_phases.heap_edit.as_micros(),
            grouped_phases.heap_edit.as_micros(),
            bulk_phases.index_edit.as_micros(),
            grouped_phases.index_edit.as_micros(),
            bulk_phases.wal_bytes,
            grouped_phases.wal_bytes,
            bulk_phases.frames,
            grouped_phases.frames,
            bulk_phases.descents,
            grouped_phases.descents,
            bulk_phases.leaf_redistributions,
            bulk_phases.leaf_merges,
            bulk_phases.internal_merges,
            bulk_phases.root_contractions,
            bulk_phases.pages_allocated,
            bulk_phases.pages_freed,
            bulk_phases.scratch_bytes,
            bulk_phases.index_singles,
            grouped_phases.index_singles,
            bulk_phases.leaf_batches,
        );
        BulkSample {
            bulk_us,
            grouped_us,
            bulk_index_us: bulk_phases.index_edit.as_micros(),
            grouped_index_us: grouped_phases.index_edit.as_micros(),
            bulk_wal: bulk_phases.wal_bytes,
            grouped_wal: grouped_phases.wal_bytes,
            spans: bulk_phases.bulk_spans,
            merges: bulk_phases.leaf_merges,
            internal_merges: bulk_phases.internal_merges,
            contractions: bulk_phases.root_contractions,
            allocated: bulk_phases.pages_allocated,
            freed: bulk_phases.pages_freed,
            scratch: bulk_phases.scratch_bytes,
            singles: bulk_phases.index_singles,
            grouped_singles: grouped_phases.index_singles,
            descents: bulk_phases.descents,
            leaf_decodes: bulk_phases.leaf_decodes,
            sibling_steps: bulk_phases.sibling_steps,
            posting_compares: bulk_phases.posting_compares,
            duplicate_checks: bulk_phases.duplicate_checks,
            ordered_verified: bulk_phases.ordered_verified,
            fallback_verified: bulk_phases.fallback_verified,
            presence_verified: bulk_phases.presence_verified,
            presence_builds: bulk_phases.presence_builds,
            map_bytes: bulk_phases.map_bytes,
            map_hits: bulk_phases.map_hits,
            map_misses: bulk_phases.map_misses,
            presence_build_us: bulk_phases.presence_build.as_micros(),
            presence_member_us: bulk_phases.presence_member.as_micros(),
            early_plans: bulk_phases.early_plans,
            estimated_pages: bulk_phases.estimated_pages,
            scanned_pages: bulk_phases.scanned_pages,
            validations_skipped: bulk_phases.validations_skipped,
            tree_validations: bulk_phases.tree_validations,
            path_us: bulk_phases.path_record.as_micros(),
            reused_paths: bulk_phases.reused_paths,
            path_invalidations: bulk_phases.path_invalidations,
            ancestor_reads: bulk_phases.ancestor_reads,
            ancestor_writes: bulk_phases.ancestor_writes,
            separator_updates: bulk_phases.separator_updates,
            index_pages: bulk_phases.index_pages,
            grouped_postings: bulk_phases.leaf_batches,
            id_height,
            id_pages,
            checksum,
        }
    }

    #[test]
    fn ordered_posting_run_matches_descent_verification() {
        let _phases = crate::storage::enable_phases();
        let (_dir, base) = seed_delete_db("m32-agree", 2_000, 0x3200);
        let statements = [
            ("one", "DELETE FROM users WHERE id = 1;"),
            ("half", "DELETE FROM users WHERE id < 1000;"),
            ("duplicates", "DELETE FROM users WHERE bucket = 1;"),
            ("alternating", "DELETE FROM users WHERE active = TRUE;"),
            ("bucket", "DELETE FROM users WHERE bucket = 0;"),
            ("all", "DELETE FROM users WHERE TRUE OR id = 0;"),
        ];
        for (label, sql) in statements {
            let (_ordered_dir, ordered_path, mut ordered) =
                open_copy(&base, &format!("m32-{label}-o"));
            let (_descent_dir, descent_path, mut descent) =
                open_copy(&base, &format!("m32-{label}-d"));
            let origin_next = ordered.table("users").unwrap().next_row_id();
            crate::storage::reset_phases();
            let ordered_count = change_count(&mut ordered, sql);
            let ordered_phases = crate::storage::take_phases();
            crate::storage::reset_phases();
            let descent_count = {
                let _guard = crate::storage::ForceDescentVerify::new();
                change_count(&mut descent, sql)
            };
            let descent_phases = crate::storage::take_phases();
            assert_eq!(ordered_count, descent_count, "{label}");
            assert_eq!(
                mutation_checksum(&mut ordered),
                mutation_checksum(&mut descent),
                "{label}"
            );
            assert_eq!(
                table_rows(&mut ordered),
                table_rows(&mut descent),
                "{label}"
            );
            assert_eq!(
                ordered.table("users").unwrap().row_ids(),
                descent.table("users").unwrap().row_ids(),
                "{label}"
            );
            assert_eq!(
                ordered.table("users").unwrap().next_row_id(),
                origin_next,
                "{label}"
            );
            assert_eq!(
                index_postings(&mut ordered, "idx_users_id"),
                index_postings(&mut descent, "idx_users_id"),
                "{label}"
            );
            assert_eq!(
                index_postings(&mut ordered, "idx_users_bucket"),
                index_postings(&mut descent, "idx_users_bucket"),
                "{label}"
            );
            assert_eq!(
                ordered.index_shape("idx_users_id").unwrap(),
                descent.index_shape("idx_users_id").unwrap(),
                "{label}"
            );
            assert_eq!(db_file(&ordered_path), db_file(&descent_path), "{label}");
            assert_eq!(wal_len(&ordered_path), wal_len(&descent_path), "{label}");
            assert_eq!(
                ordered_phases.bulk_spans, descent_phases.bulk_spans,
                "{label}"
            );
            assert_eq!(
                ordered_phases.wal_bytes, descent_phases.wal_bytes,
                "{label}"
            );
            if label == "one" {
                assert_eq!(ordered_phases.bulk_spans, 0, "{label}");
                assert!(
                    ordered_phases.index_singles >= 1,
                    "{label} {ordered_phases:?}"
                );
                assert_eq!(ordered_phases.descents, descent_phases.descents, "{label}");
            }
            if matches!(label, "half" | "all" | "alternating") {
                assert!(
                    ordered_phases.descents < descent_phases.descents,
                    "{label} ordered {} descent {} verified {} fallback {}",
                    ordered_phases.descents,
                    descent_phases.descents,
                    ordered_phases.ordered_verified,
                    ordered_phases.fallback_verified
                );
                assert!(
                    ordered_phases.ordered_verified > 0,
                    "{label} {ordered_phases:?}"
                );
            }
            let checksum = mutation_checksum(&mut ordered);
            let ordered_lookup = query(&mut ordered, "SELECT id FROM users WHERE id = 1;")
                .rows
                .len();
            let descent_lookup = query(&mut descent, "SELECT id FROM users WHERE id = 1;")
                .rows
                .len();
            assert_eq!(ordered_lookup, descent_lookup, "{label}");
            drop(ordered);
            let mut reopened = Database::open(&ordered_path).unwrap();
            assert_eq!(mutation_checksum(&mut reopened), checksum, "{label}");
            assert_eq!(
                query(&mut reopened, "SELECT id FROM users WHERE id = 1;")
                    .rows
                    .len(),
                ordered_lookup,
                "{label}"
            );
        }
        assert_precommit(
            &base,
            "m32-pre-half",
            "DELETE FROM users WHERE id < 1000;",
            crate::storage::Inject::BeforeLogSync,
        );
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(
                &base,
                &format!("m32-post-half-{inject:?}"),
                "DELETE FROM users WHERE id < 1000;",
                inject,
            );
        }
        assert_precommit(
            &base,
            "m32-pre-active",
            "DELETE FROM users WHERE active = TRUE;",
            crate::storage::Inject::BeforeLogSync,
        );
    }

    #[test]
    fn presence_map_matches_chain_and_descent_deletion() {
        let _phases = crate::storage::enable_phases();
        let (_dir, base) = seed_delete_db("m33-agree", 2_000, 0x3300);
        let statements = [
            ("none", "DELETE FROM users WHERE id = -1;"),
            ("one", "DELETE FROM users WHERE id = 1;"),
            ("ten", "DELETE FROM users WHERE id >= 1 AND id <= 10;"),
            ("half", "DELETE FROM users WHERE id < 1000;"),
            (
                "buckets",
                "DELETE FROM users WHERE bucket = 0 OR bucket = 1;",
            ),
            ("alternating", "DELETE FROM users WHERE active = TRUE;"),
            ("all", "DELETE FROM users WHERE TRUE OR id = 0;"),
        ];
        for (label, sql) in statements {
            let (_presence_dir, presence_path, mut presence) =
                open_copy(&base, &format!("m33-{label}-p"));
            let (_chain_dir, chain_path, mut chain) = open_copy(&base, &format!("m33-{label}-c"));
            let (_descent_dir, _descent_path, mut descent) =
                open_copy(&base, &format!("m33-{label}-d"));
            let origin_next = presence.table("users").unwrap().next_row_id();
            crate::storage::reset_phases();
            let presence_count = change_count(&mut presence, sql);
            let presence_phases = crate::storage::take_phases();
            crate::storage::reset_phases();
            let chain_count = {
                let _guard = crate::storage::ForceChainVerify::new();
                change_count(&mut chain, sql)
            };
            let chain_phases = crate::storage::take_phases();
            crate::storage::reset_phases();
            let descent_count = {
                let _guard = crate::storage::ForceDescentVerify::new();
                change_count(&mut descent, sql)
            };
            assert_eq!(presence_count, chain_count, "{label}");
            assert_eq!(presence_count, descent_count, "{label}");
            assert_eq!(
                mutation_checksum(&mut presence),
                mutation_checksum(&mut chain),
                "{label}"
            );
            assert_eq!(
                mutation_checksum(&mut presence),
                mutation_checksum(&mut descent),
                "{label}"
            );
            assert_eq!(table_rows(&mut presence), table_rows(&mut chain), "{label}");
            assert_eq!(
                presence.table("users").unwrap().row_ids(),
                chain.table("users").unwrap().row_ids(),
                "{label}"
            );
            assert_eq!(
                presence.table("users").unwrap().next_row_id(),
                origin_next,
                "{label}"
            );
            for index in ["idx_users_id", "idx_users_bucket"] {
                assert_eq!(
                    index_postings(&mut presence, index),
                    index_postings(&mut chain, index),
                    "{label} {index}"
                );
                assert_eq!(
                    index_postings(&mut presence, index),
                    index_postings(&mut descent, index),
                    "{label} {index}"
                );
            }
            assert_eq!(
                presence.index_shape("idx_users_id").unwrap(),
                chain.index_shape("idx_users_id").unwrap(),
                "{label}"
            );
            assert_eq!(db_file(&presence_path), db_file(&chain_path), "{label}");
            assert_eq!(presence_phases.wal_bytes, chain_phases.wal_bytes, "{label}");
            assert_eq!(
                presence_phases.bulk_spans, chain_phases.bulk_spans,
                "{label}"
            );
            if matches!(label, "none" | "one" | "ten") {
                assert_eq!(
                    presence_phases.presence_builds, 0,
                    "{label} {presence_phases:?}"
                );
            }
            if matches!(label, "half" | "buckets" | "alternating" | "all") {
                assert!(
                    presence_phases.presence_verified > 0,
                    "{label} {presence_phases:?}"
                );
                assert!(
                    presence_phases.descents < chain_phases.descents,
                    "{label} presence {} chain {}",
                    presence_phases.descents,
                    chain_phases.descents
                );
            }
            let checksum = mutation_checksum(&mut presence);
            drop(presence);
            let mut reopened = Database::open(&presence_path).unwrap();
            assert_eq!(mutation_checksum(&mut reopened), checksum, "{label}");
            assert_eq!(
                query(&mut reopened, "SELECT id FROM users WHERE id = 1;")
                    .rows
                    .len(),
                query(&mut chain, "SELECT id FROM users WHERE id = 1;")
                    .rows
                    .len(),
                "{label}"
            );
            let bucket = index_postings(&mut reopened, "idx_users_bucket");
            drop(reopened);
            let mut again = Database::open(&presence_path).unwrap();
            assert_eq!(mutation_checksum(&mut again), checksum, "{label}");
            assert_eq!(
                index_postings(&mut again, "idx_users_bucket"),
                bucket,
                "{label}"
            );
            if label == "half" {
                assert!(
                    presence_phases.bulk_spans >= 2,
                    "{label} spans {}",
                    presence_phases.bulk_spans
                );
                assert!(
                    presence_phases.presence_builds >= 1,
                    "{label} {presence_phases:?}"
                );
            }
        }

        let (_dir, path, mut db) = open_copy(&base, "m33-update");
        db.execute("UPDATE users SET bucket = 3 WHERE id = 40;")
            .unwrap();
        db.execute("UPDATE users SET name = 'relocated-name-with-extra-bytes' WHERE id = 41;")
            .unwrap();
        let updated = change_count(&mut db, "DELETE FROM users WHERE id < 1000;");
        assert!(updated >= 999);
        db.execute("INSERT INTO users VALUES (9000, 'again', TRUE, 1);")
            .unwrap();
        assert_eq!(
            query(&mut db, "SELECT id FROM users WHERE id = 9000;")
                .rows
                .len(),
            1
        );
        let second = change_count(&mut db, "DELETE FROM users WHERE id = 1;");
        assert_eq!(second, 0);
        let checksum = mutation_checksum(&mut db);
        drop(db);
        let mut reopened = Database::open(&path).unwrap();
        assert_eq!(mutation_checksum(&mut reopened), checksum);

        assert_precommit(
            &base,
            "m33-pre-half",
            "DELETE FROM users WHERE id < 1000;",
            crate::storage::Inject::BeforeLogSync,
        );
        {
            let _guard = crate::storage::ForceChainVerify::new();
            assert_precommit(
                &base,
                "m33-pre-half-chain",
                "DELETE FROM users WHERE id < 1000;",
                crate::storage::Inject::BeforeLogSync,
            );
        }
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(
                &base,
                &format!("m33-post-half-{inject:?}"),
                "DELETE FROM users WHERE id < 1000;",
                inject,
            );
            assert_postcommit(
                &base,
                &format!("m33-post-buckets-{inject:?}"),
                "DELETE FROM users WHERE bucket = 0 OR bucket = 1;",
                inject,
            );
        }

        let batches = [
            "DELETE FROM users WHERE id < 800;",
            "DELETE FROM users WHERE id >= 1400;",
        ];
        let (_batch_dir, batch_path, mut presence) = open_copy(&base, "m33-batches-p");
        let (_chain_dir, _, mut chain) = open_copy(&base, "m33-batches-c");
        let (_descent_dir, _, mut descent) = open_copy(&base, "m33-batches-d");
        for sql in batches {
            let presence_count = change_count(&mut presence, sql);
            let chain_count = {
                let _guard = crate::storage::ForceChainVerify::new();
                change_count(&mut chain, sql)
            };
            let descent_count = {
                let _guard = crate::storage::ForceDescentVerify::new();
                change_count(&mut descent, sql)
            };
            assert_eq!(presence_count, chain_count, "{sql}");
            assert_eq!(presence_count, descent_count, "{sql}");
            assert_eq!(table_rows(&mut presence), table_rows(&mut chain), "{sql}");
            assert_eq!(table_rows(&mut presence), table_rows(&mut descent), "{sql}");
            let ids = presence.table("users").unwrap().row_ids().to_vec();
            let rows = table_rows(&mut presence);
            assert_eq!(
                index_postings(&mut presence, "idx_users_id"),
                reference_postings(&rows, &ids, 0),
                "{sql}"
            );
            assert_eq!(
                index_postings(&mut presence, "idx_users_bucket"),
                reference_postings(&rows, &ids, 3),
                "{sql}"
            );
            assert_eq!(
                index_postings(&mut presence, "idx_users_id"),
                index_postings(&mut chain, "idx_users_id"),
                "{sql}"
            );
            assert_eq!(
                index_postings(&mut presence, "idx_users_bucket"),
                index_postings(&mut descent, "idx_users_bucket"),
                "{sql}"
            );
        }
        let batch_checksum = mutation_checksum(&mut presence);
        drop(presence);
        let mut once = Database::open(&batch_path).unwrap();
        assert_eq!(mutation_checksum(&mut once), batch_checksum);
        drop(once);
        let mut twice = Database::open(&batch_path).unwrap();
        assert_eq!(mutation_checksum(&mut twice), batch_checksum);
        let ids = twice.table("users").unwrap().row_ids().to_vec();
        let rows = table_rows(&mut twice);
        assert_eq!(
            index_postings(&mut twice, "idx_users_id"),
            reference_postings(&rows, &ids, 0)
        );
        assert_eq!(
            index_postings(&mut twice, "idx_users_bucket"),
            reference_postings(&rows, &ids, 3)
        );

        let (_mixed_dir, mixed_path, mut mixed) = open_copy(&base, "m33-mixed");
        let (_mixed_chain_dir, _, mut mixed_chain) = open_copy(&base, "m33-mixed-c");
        for sql in [
            "DELETE FROM users WHERE id = 1;",
            "DELETE FROM users WHERE bucket = 0 OR bucket = 1;",
        ] {
            let left = change_count(&mut mixed, sql);
            let right = {
                let _guard = crate::storage::ForceChainVerify::new();
                change_count(&mut mixed_chain, sql)
            };
            assert_eq!(left, right, "{sql}");
            assert_eq!(
                table_rows(&mut mixed),
                table_rows(&mut mixed_chain),
                "{sql}"
            );
            assert_eq!(
                index_postings(&mut mixed, "idx_users_bucket"),
                index_postings(&mut mixed_chain, "idx_users_bucket"),
                "{sql}"
            );
        }
        let mixed_checksum = mutation_checksum(&mut mixed);
        drop(mixed);
        let mut mixed_again = Database::open(&mixed_path).unwrap();
        assert_eq!(mutation_checksum(&mut mixed_again), mixed_checksum);
        drop(mixed_again);
        let mut mixed_twice = Database::open(&mixed_path).unwrap();
        assert_eq!(mutation_checksum(&mut mixed_twice), mixed_checksum);

        let (contract_dir, contracted, mut contracted_db) = open_copy(&base, "m33-contract-src");
        let before_height = contracted_db.index_shape("idx_users_id").unwrap().0;
        change_count(&mut contracted_db, "DELETE FROM users WHERE id < 1900;");
        let after_height = contracted_db.index_shape("idx_users_id").unwrap().0;
        assert!(
            after_height < before_height,
            "id height {before_height} -> {after_height}"
        );
        drop(contracted_db);
        assert_precommit(
            &contracted,
            "m33-pre-second",
            "DELETE FROM users WHERE id >= 1900;",
            crate::storage::Inject::BeforeLogSync,
        );
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(
                &contracted,
                &format!("m33-post-second-{inject:?}"),
                "DELETE FROM users WHERE id >= 1900;",
                inject,
            );
        }
        drop(contract_dir);

        assert_precommit(
            &base,
            "m33-pre-all",
            "DELETE FROM users WHERE TRUE OR id = 0;",
            crate::storage::Inject::BeforeLogSync,
        );
        {
            let _guard = crate::storage::ForceDescentVerify::new();
            assert_precommit(
                &base,
                "m33-pre-all-descent",
                "DELETE FROM users WHERE TRUE OR id = 0;",
                crate::storage::Inject::BeforeLogSync,
            );
        }
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(
                &base,
                &format!("m33-post-all-{inject:?}"),
                "DELETE FROM users WHERE TRUE OR id = 0;",
                inject,
            );
        }
    }

