    #[test]
    #[ignore = "release profile of validated-path reuse"]
    fn profile_milestone35() {
        let cpu = profile_command("sysctl", &["-n", "machdep.cpu.brand_string"]);
        let mem = profile_command("sysctl", &["-n", "hw.memsize"]);
        let rustc = profile_command("rustc", &["--version"]);
        println!("milestone35 cpu={cpu} mem_bytes={mem} rustc={rustc}");
        let _phases = crate::storage::enable_phases();
        for rows in [100_i64, 1_000, 10_000, 100_000] {
            let (_base_dir, base) = seed_delete_db("m35-base", rows, 0x3100);
            let samples = if rows == 100_000 { 3 } else { 1 };
            for workload in [
                "one",
                "ten",
                "buckets",
                "half",
                "sparse",
                "alternating",
                "consecutive",
                "all",
                "wide",
            ] {
                let mut current = Vec::with_capacity(samples);
                let mut prior = Vec::with_capacity(samples);
                let mut late = Vec::with_capacity(samples);
                let mut chain = Vec::with_capacity(samples);
                for sample in 0..samples {
                    current.push(profile_bulk_delete(
                        &base,
                        rows,
                        workload,
                        sample,
                        VerifyMode::Presence,
                    ));
                    prior.push(profile_bulk_delete(
                        &base,
                        rows,
                        workload,
                        sample,
                        VerifyMode::Prior,
                    ));
                    late.push(profile_bulk_delete(
                        &base,
                        rows,
                        workload,
                        sample,
                        VerifyMode::Late,
                    ));
                    chain.push(profile_bulk_delete(
                        &base,
                        rows,
                        workload,
                        sample,
                        VerifyMode::Chain,
                    ));
                }
                for (index, sample) in current.iter().enumerate() {
                    let previous = &prior[index];
                    let deferred = &late[index];
                    let ordered = &chain[index];
                    assert_eq!(sample.checksum, previous.checksum, "{workload} {rows}");
                    assert_eq!(sample.checksum, deferred.checksum, "{workload} {rows}");
                    assert_eq!(sample.checksum, ordered.checksum, "{workload} {rows}");
                    assert_eq!(sample.bulk_wal, deferred.bulk_wal, "{workload} {rows}");
                    assert_eq!(sample.bulk_wal, ordered.bulk_wal, "{workload} {rows}");
                    assert_eq!(sample.spans, previous.spans, "{workload} {rows}");
                    assert_eq!(sample.singles, previous.singles, "{workload} {rows}");
                    assert_eq!(sample.id_height, previous.id_height, "{workload} {rows}");
                    assert_eq!(sample.id_pages, previous.id_pages, "{workload} {rows}");
                    if sample.reused_paths > 0 {
                        assert!(
                            sample.descents < previous.descents,
                            "{workload} {rows} reused {} prior {}",
                            sample.descents,
                            previous.descents
                        );
                    }
                }
                if rows == 1_000 && workload == "ten" {
                    assert_eq!(current[0].early_plans, 0, "ten keys must not build a map");
                    assert!(
                        prior[0].early_plans >= 1,
                        "milestone 34 planned this request: {:?}",
                        prior[0].early_plans
                    );
                }
                if rows == 100_000 && workload == "all" {
                    assert!(current[0].reused_paths > 0, "{:?}", current[0].reused_paths);
                    assert!(current[0].descents < prior[0].descents);
                }
                let current_us = median(
                    &current
                        .iter()
                        .map(|sample| sample.bulk_us)
                        .collect::<Vec<_>>(),
                );
                let prior_us = median(
                    &prior
                        .iter()
                        .map(|sample| sample.bulk_us)
                        .collect::<Vec<_>>(),
                );
                let late_us = median(&late.iter().map(|sample| sample.bulk_us).collect::<Vec<_>>());
                let chain_us = median(
                    &chain
                        .iter()
                        .map(|sample| sample.bulk_us)
                        .collect::<Vec<_>>(),
                );
                let current_index = median(
                    &current
                        .iter()
                        .map(|sample| sample.bulk_index_us)
                        .collect::<Vec<_>>(),
                );
                let prior_index = median(
                    &prior
                        .iter()
                        .map(|sample| sample.bulk_index_us)
                        .collect::<Vec<_>>(),
                );
                let sample = &current[0];
                let previous = &prior[0];
                println!(
                    "milestone35 median workload={workload} rows={rows} samples={samples} current_us={current_us} prior_us={prior_us} late_us={late_us} chain_us={chain_us} current_index_us={current_index} prior_index_us={prior_index} wal={} prior_wal={} checksum={} descents={} prior_descents={} reused={} invalidations={} early_plans={} prior_plans={} estimated_pages={} scanned_pages={} builds={} build_us={} member_us={} path_us={} validations={} map_bytes={} spans={} singles={} grouped_postings={} allocated={} freed={} scratch={} verified={}",
                    sample.bulk_wal,
                    previous.bulk_wal,
                    sample.checksum,
                    sample.descents,
                    previous.descents,
                    sample.reused_paths,
                    sample.path_invalidations,
                    sample.early_plans,
                    previous.early_plans,
                    sample.estimated_pages,
                    sample.scanned_pages,
                    sample.presence_builds,
                    sample.presence_build_us,
                    sample.presence_member_us,
                    sample.path_us,
                    sample.tree_validations,
                    sample.map_bytes,
                    sample.spans,
                    sample.singles,
                    sample.grouped_postings,
                    sample.allocated,
                    sample.freed,
                    sample.scratch,
                    sample.presence_verified
                );
            }
        }
    }

    #[test]
    fn selective_ancestor_delete_matches_full_rewrite_and_recovers() {
        let _phases = crate::storage::enable_phases();
        let (_dir, base) = seed_delete_db("m36-agree", 2_000, 0x3600);
        let wide = format!("DELETE FROM users WHERE name = '{}';", "w".repeat(80));
        let statements = [
            ("one", "DELETE FROM users WHERE id = 1;".to_string()),
            (
                "ten",
                "DELETE FROM users WHERE id >= 1 AND id <= 10;".to_string(),
            ),
            (
                "buckets",
                "DELETE FROM users WHERE bucket = 0 OR bucket = 1;".to_string(),
            ),
            ("half", "DELETE FROM users WHERE id < 1000;".to_string()),
            (
                "alternating",
                "DELETE FROM users WHERE active = TRUE;".to_string(),
            ),
            (
                "consecutive",
                "DELETE FROM users WHERE id >= 1 AND id < 500;".to_string(),
            ),
            (
                "sparse",
                "DELETE FROM users WHERE bucket IS NULL;".to_string(),
            ),
            ("all", "DELETE FROM users WHERE TRUE OR id = 0;".to_string()),
            ("wide", wide),
        ];
        for (label, sql) in &statements {
            let (_selective_dir, selective_path, mut selective) =
                open_copy(&base, &format!("m36-{label}-s"));
            let (_sealed_dir, _, mut sealed) = open_copy(&base, &format!("m36-{label}-f"));
            crate::storage::reset_phases();
            let selective_count = change_count(&mut selective, sql);
            let selective_phases = crate::storage::take_phases();
            crate::storage::reset_phases();
            let sealed_count = {
                let _guard = crate::storage::ForceAncestorRewrite::new();
                change_count(&mut sealed, sql)
            };
            let sealed_phases = crate::storage::take_phases();
            assert_eq!(selective_count, sealed_count, "{label}");
            assert_eq!(
                mutation_checksum(&mut selective),
                mutation_checksum(&mut sealed),
                "{label}"
            );
            assert_eq!(
                selective.table("users").unwrap().row_ids(),
                sealed.table("users").unwrap().row_ids(),
                "{label}"
            );
            assert_eq!(
                selective.table("users").unwrap().next_row_id(),
                sealed.table("users").unwrap().next_row_id(),
                "{label}"
            );
            for index in ["idx_users_id", "idx_users_bucket"] {
                assert_eq!(
                    index_postings(&mut selective, index),
                    index_postings(&mut sealed, index),
                    "{label} {index}"
                );
            }
            assert_eq!(
                selective_phases.separator_updates, sealed_phases.separator_updates,
                "{label}"
            );
            assert!(
                selective_phases.ancestor_writes <= sealed_phases.ancestor_writes,
                "{label} selective {} sealed {}",
                selective_phases.ancestor_writes,
                sealed_phases.ancestor_writes
            );
            assert!(
                selective_phases.wal_bytes <= sealed_phases.wal_bytes,
                "{label} selective {} sealed {}",
                selective_phases.wal_bytes,
                sealed_phases.wal_bytes
            );
            let checksum = mutation_checksum(&mut selective);
            drop(selective);
            let mut reopened = Database::open(&selective_path).unwrap();
            assert_eq!(mutation_checksum(&mut reopened), checksum, "{label}");
            drop(reopened);
            let mut again = Database::open(&selective_path).unwrap();
            assert_eq!(mutation_checksum(&mut again), checksum, "{label}");
        }
        for (label, sql) in [
            ("ten", "DELETE FROM users WHERE id >= 1 AND id <= 10;"),
            (
                "buckets",
                "DELETE FROM users WHERE bucket = 0 OR bucket = 1;",
            ),
            ("all", "DELETE FROM users WHERE TRUE OR id = 0;"),
        ] {
            assert_precommit(
                &base,
                &format!("m36-pre-{label}"),
                sql,
                crate::storage::Inject::BeforeLogSync,
            );
            for inject in [
                crate::storage::Inject::AfterLogSync,
                crate::storage::Inject::CommitSyncFailed,
                crate::storage::Inject::DuringCheckpoint(1),
            ] {
                assert_postcommit(&base, &format!("m36-post-{label}-{inject:?}"), sql, inject);
            }
        }
    }

    #[test]
    fn profiled_statement_matches_unprofiled_result_and_injections() {
        let (_dir, base) = seed_delete_db("m39-agree", 300, 0x3900);
        let delete_sql = "DELETE FROM users WHERE bucket = 0 OR bucket = 1;";
        let (_off_dir, off_path, mut off) = open_copy(&base, "m39-off");
        let (_on_dir, on_path, mut on) = open_copy(&base, "m39-on");
        let off_count = change_count(&mut off, delete_sql);
        let on_count = {
            let _phases = crate::storage::enable_phases();
            change_count(&mut on, delete_sql)
        };
        assert_eq!(off_count, on_count);
        assert_eq!(db_file(&off_path), db_file(&on_path));
        assert_eq!(mutation_checksum(&mut off), mutation_checksum(&mut on));
        assert_eq!(
            off.table("users").unwrap().row_ids(),
            on.table("users").unwrap().row_ids()
        );
        assert_eq!(
            off.table("users").unwrap().next_row_id(),
            on.table("users").unwrap().next_row_id()
        );
        assert_eq!(wal_len(&off_path), 0);
        assert_eq!(wal_len(&on_path), 0);
        let update_sql = "UPDATE users SET name = 'edited' WHERE id = 2;";
        assert_eq!(change_count(&mut off, update_sql), {
            let _phases = crate::storage::enable_phases();
            change_count(&mut on, update_sql)
        });
        assert_eq!(db_file(&off_path), db_file(&on_path));
        let insert_sql = "INSERT INTO users VALUES (301, 'added', TRUE, 1);";
        let off_insert = off.execute(insert_sql).unwrap().pop().unwrap();
        let on_insert = {
            let _phases = crate::storage::enable_phases();
            on.execute(insert_sql).unwrap().pop().unwrap()
        };
        assert_eq!(off_insert, on_insert);
        assert_eq!(db_file(&off_path), db_file(&on_path));
        let select_sql = "SELECT id, name FROM users WHERE id = 3;";
        let off_rows = off.execute(select_sql).unwrap().pop().unwrap();
        let on_rows = {
            let _phases = crate::storage::enable_phases();
            on.execute(select_sql).unwrap().pop().unwrap()
        };
        assert_eq!(off_rows, on_rows);
        let _phases = crate::storage::enable_phases();
        assert_precommit(
            &base,
            "m39-pre",
            delete_sql,
            crate::storage::Inject::BeforeLogSync,
        );
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(&base, &format!("m39-post-{inject:?}"), delete_sql, inject);
        }
    }

    #[test]
    fn fresh_seal_matches_full_recheck_and_keeps_recovery() {
        let (_dir, base) = seed_delete_db("m40-agree", 400, 0x4000);
        for sql in [
            "DELETE FROM users WHERE id = 1;",
            "DELETE FROM users WHERE id >= 1 AND id <= 10;",
            "DELETE FROM users WHERE bucket = 0 OR bucket = 1;",
            "DELETE FROM users WHERE TRUE OR id = 0;",
            "UPDATE users SET name = 'edited' WHERE id = 2;",
            "UPDATE users SET name = 'edited' WHERE active = TRUE;",
            "INSERT INTO users VALUES (401, 'added', TRUE, 1);",
        ] {
            let (_fresh_dir, fresh_path, mut fresh) = open_copy(&base, "m40-fresh");
            let (_full_dir, full_path, mut full) = open_copy(&base, "m40-full");
            let _phases = crate::storage::enable_phases();
            crate::storage::reset_phases();
            let fresh_result = fresh.execute(sql).unwrap();
            let fresh_phases = crate::storage::take_phases();
            crate::storage::reset_phases();
            let full_result = {
                let _recheck = crate::storage::ForceChecksumRecheck::new();
                full.execute(sql).unwrap()
            };
            let full_phases = crate::storage::take_phases();
            assert_eq!(fresh_result, full_result, "{sql}");
            assert_eq!(db_file(&fresh_path), db_file(&full_path), "{sql}");
            assert_eq!(
                mutation_checksum(&mut fresh),
                mutation_checksum(&mut full),
                "{sql}"
            );
            assert_eq!(
                fresh.table("users").unwrap().row_ids(),
                full.table("users").unwrap().row_ids(),
                "{sql}"
            );
            assert_eq!(
                fresh.table("users").unwrap().next_row_id(),
                full.table("users").unwrap().next_row_id(),
                "{sql}"
            );
            assert_eq!(table_rows(&mut fresh), table_rows(&mut full), "{sql}");
            assert_eq!(
                index_postings(&mut fresh, "idx_users_id"),
                index_postings(&mut full, "idx_users_id"),
                "{sql}"
            );
            assert_eq!(
                index_postings(&mut fresh, "idx_users_bucket"),
                index_postings(&mut full, "idx_users_bucket"),
                "{sql}"
            );
            assert_eq!(fresh_phases.wal_bytes, full_phases.wal_bytes, "{sql}");
            assert_eq!(fresh_phases.frames, full_phases.frames, "{sql}");
            assert_eq!(fresh_phases.heap_pages, full_phases.heap_pages, "{sql}");
            assert_eq!(fresh_phases.index_pages, full_phases.index_pages, "{sql}");
            assert_eq!(fresh_phases.other_pages, full_phases.other_pages, "{sql}");
            assert_eq!(
                fresh_phases.page_recheck,
                std::time::Duration::ZERO,
                "{sql}"
            );
            assert!(
                full_phases.page_recheck > std::time::Duration::ZERO,
                "{sql}"
            );
            assert_eq!(wal_len(&fresh_path), 0, "{sql}");
            assert_eq!(wal_len(&full_path), 0, "{sql}");
            drop(fresh);
            drop(full);
            let mut reopened = Database::open(&fresh_path).unwrap();
            let mut full_open = Database::open(&full_path).unwrap();
            assert_eq!(
                mutation_checksum(&mut reopened),
                mutation_checksum(&mut full_open),
                "{sql}"
            );
            drop(reopened);
            let again = Database::open(&fresh_path).unwrap();
            assert_eq!(db_file(&fresh_path), db_file(&full_path), "{sql}");
            drop(again);
        }
        let delete_sql = "DELETE FROM users WHERE bucket = 0 OR bucket = 1;";
        let wal_of = |label: &str, recheck: bool| -> Vec<u8> {
            let (_dir, path, mut db) = open_copy(&base, label);
            db.set_inject(crate::storage::Inject::AfterLogSync);
            let error = if recheck {
                let _recheck = crate::storage::ForceChecksumRecheck::new();
                db.execute(delete_sql)
            } else {
                db.execute(delete_sql)
            };
            assert!(error.is_err(), "{label}");
            let bytes = wal_bytes(&path);
            assert!(bytes.len() > 32, "{label} {}", bytes.len());
            bytes
        };
        assert_eq!(wal_of("m40-wal-fresh", false), wal_of("m40-wal-full", true));
        assert_precommit(
            &base,
            "m40-pre",
            delete_sql,
            crate::storage::Inject::BeforeLogSync,
        );
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(&base, &format!("m40-post-{inject:?}"), delete_sql, inject);
        }
        let (_disk_dir, disk_path) = seed_delete_db("m40-disk", 40, 0x4001);
        let mut bytes = std::fs::read(&disk_path).unwrap();
        assert!(bytes.len() > 5_000, "{}", bytes.len());
        bytes[5_000] ^= 0xff;
        std::fs::write(&disk_path, &bytes).unwrap();
        let error = match Database::open(&disk_path) {
            Err(error) => error.to_string(),
            Ok(_) => panic!("a flipped database byte opened"),
        };
        assert!(error.contains("corrupt"), "{error}");
    }

    #[test]
    #[ignore = "release profile of end-to-end statement stages"]
    fn profile_milestone39() {
        let cpu = profile_command("sysctl", &["-n", "machdep.cpu.brand_string"]);
        let mem = profile_command("sysctl", &["-n", "hw.memsize"]);
        let os = profile_command("uname", &["-smr"]);
        let rustc = profile_command("rustc", &["--version"]);
        println!(
            "milestone39 cpu={cpu} mem_bytes={mem} os={os} rustc={rustc} build=release-test seed=0x3100 warmup=1"
        );
        let _phases = crate::storage::enable_phases();
        for rows in [100_i64, 1_000, 10_000, 100_000] {
            let (_base_dir, base) = seed_delete_db("m39-base", rows, 0x3100);
            let file_len = std::fs::metadata(&base).unwrap().len();
            println!(
                "milestone39 database rows={rows} file_bytes={file_len} indexes=idx_users_id,idx_users_bucket"
            );
            let samples = if rows >= 10_000 { 3 } else { 1 };
            for kind in [
                "one",
                "ten",
                "buckets",
                "half",
                "alternating",
                "consecutive",
                "sparse",
                "all",
                "wide",
            ] {
                milestone39_workload(&base, rows, kind, samples, true);
            }
            for kind in [
                "select-index",
                "select-scan",
                "update-index",
                "update-scan",
                "insert-one",
                "insert-batch",
                "join",
                "group",
            ] {
                let repeats = if rows == 100_000 { 1 } else { samples };
                milestone39_workload(&base, rows, kind, repeats, false);
            }
            if rows == 1_000 {
                milestone39_overhead(&base, rows);
            }
            if rows == 100_000 {
                milestone39_nosync(&base, rows);
            }
        }
    }

    fn milestone39_overhead(base: &std::path::Path, rows: i64) {
        let sql = milestone39_sql("all", rows);
        let mut off = Vec::new();
        let mut on = Vec::new();
        for sample in 0..5 {
            let off_first = sample % 2 == 0;
            let measure = |label: &str, enabled: bool| -> u128 {
                crate::storage::set_phases_enabled(enabled);
                let (_dir, _, mut db) = open_copy(base, &format!("m39-{label}-{sample}"));
                db.execute("SELECT COUNT(*) FROM users;").unwrap();
                if enabled {
                    crate::storage::reset_phases();
                }
                let started = std::time::Instant::now();
                change_count(&mut db, &sql);
                started.elapsed().as_micros()
            };
            if off_first {
                off.push(measure("off", false));
                on.push(measure("on", true));
            } else {
                on.push(measure("on", true));
                off.push(measure("off", false));
            }
        }
        crate::storage::set_phases_enabled(true);
        println!(
            "milestone39 overhead rows={rows} workload=all samples=5 alternate=sample_index off_median_us={} on_median_us={} off_min_us={} off_max_us={} on_min_us={} on_max_us={}",
            median(&off),
            median(&on),
            off.iter().min().copied().unwrap_or(0),
            off.iter().max().copied().unwrap_or(0),
            on.iter().min().copied().unwrap_or(0),
            on.iter().max().copied().unwrap_or(0)
        );
    }

    fn milestone39_nosync(base: &std::path::Path, rows: i64) {
        let sql = milestone39_sql("all", rows);
        let mut durable = Vec::new();
        let mut suspended = Vec::new();
        for sample in 0..3 {
            let durable_first = sample % 2 == 0;
            let run = |label: &str, skip_sync: bool| -> u128 {
                let (_dir, _, mut db) = open_copy(base, &format!("m39-sync-{label}-{sample}"));
                db.execute("SELECT COUNT(*) FROM users;").unwrap();
                crate::storage::reset_phases();
                let started = std::time::Instant::now();
                let count = if skip_sync {
                    let _guard = crate::storage::SuspendSync::new();
                    change_count(&mut db, &sql)
                } else {
                    change_count(&mut db, &sql)
                };
                let wall = started.elapsed().as_micros();
                let phases = crate::storage::take_phases();
                assert_eq!(count, usize::try_from(rows).unwrap());
                println!(
                    "milestone39 nosync sample={sample} order_durable_first={durable_first} mode={} wall_us={wall} wal_sync_us={} db_sync_us={} wal_write_us={} wal_encode_us={} NON_DURABLE={skip_sync}",
                    if skip_sync { "suspended" } else { "durable" },
                    phases.wal_sync.as_micros(),
                    phases.db_sync.as_micros(),
                    phases.wal_write.as_micros(),
                    phases.wal_encode.as_micros()
                );
                wall
            };
            if durable_first {
                durable.push(run("durable", false));
                suspended.push(run("suspended", true));
            } else {
                suspended.push(run("suspended", true));
                durable.push(run("durable", false));
            }
        }
        println!(
            "milestone39 nosync median rows={rows} workload=all durable_us={} suspended_us={} NON_DURABLE=true",
            median(&durable),
            median(&suspended)
        );
    }

    fn milestone39_workload(
        base: &std::path::Path,
        rows: i64,
        kind: &str,
        samples: usize,
        mutation_each_copy: bool,
    ) {
        let sql = milestone39_sql(kind, rows);
        let mut walls = Vec::with_capacity(samples);
        let fresh_each_time =
            mutation_each_copy || kind.starts_with("insert") || kind.starts_with("update");
        let copies = if fresh_each_time { samples } else { 1 };
        for sample in 0..copies {
            let (_dir, _, mut db) = open_copy(base, &format!("m39-{kind}-{rows}-{sample}"));
            if kind == "join" {
                db.execute("CREATE TABLE labels (bucket INT, tag TEXT);")
                    .unwrap();
                db.execute("INSERT INTO labels VALUES (0, 'a'), (1, 'b'), (2, 'c'), (3, 'd');")
                    .unwrap();
                db.execute("CREATE INDEX idx_labels_bucket ON labels(bucket);")
                    .unwrap();
            }
            let warmup = if fresh_each_time {
                "SELECT COUNT(*) FROM users;"
            } else {
                sql.as_str()
            };
            db.execute(warmup).unwrap();
            let repeats = if fresh_each_time { 1 } else { samples };
            for repeat in 0..repeats {
                let sample = if fresh_each_time { sample } else { repeat };
                crate::storage::reset_phases();
                let started = std::time::Instant::now();
                let outcome = db
                    .execute(&sql)
                    .unwrap_or_else(|error| panic!("{kind} {rows}: {error}"))
                    .pop()
                    .unwrap();
                let wall = started.elapsed().as_micros();
                let phases = crate::storage::take_phases();
                let count = match &outcome {
                    StatementResult::Delete { count }
                    | StatementResult::Update { count }
                    | StatementResult::Insert { count } => *count,
                    StatementResult::Query(rows) => rows.rows.len(),
                    StatementResult::Ok => 0,
                };
                let (exclusive, gap) = milestone39_gap(wall, &phases);
                let note = if kind.starts_with("select")
                    || kind.starts_with("insert")
                    || kind == "join"
                    || kind == "group"
                {
                    None
                } else {
                    Some(mutation_note())
                };
                println!(
                    "milestone39 sample kind={kind} rows={rows} n={sample} count={count} wall_us={wall} exclusive_us={exclusive} gap_us={gap} parse_us={} plan_us={} undo_us={} memory_us={} memory_rest_us={} prepare_us={} validate_us={} decode_us={} heap_us={} index_us={} compare_us={} gather_us={} seal_us={} verify_us={} apply_us={} apply_rest_us={} wal_encode_us={} wal_write_us={} wal_sync_us={} db_write_us={} db_sync_us={} wal_clear_us={} presence_us={} checksum={} wal_bytes={} frames={} heap_pages={} index_pages={} other_pages={} descents={} leaf_decodes={} bulk_spans={} indexes={} allocated={} freed={} ancestor_reads={} ancestor_writes={} probe_us={} validate_rows_us={} filter_us={} discover_us={} candidates={} examined={} heap_rows={} modified={}",
                    phases.parse.as_micros(),
                    phases.plan.as_micros(),
                    phases.undo.as_micros(),
                    phases.memory.as_micros(),
                    phases
                        .memory
                        .as_micros()
                        .saturating_sub(phases.plan.as_micros())
                        .saturating_sub(phases.undo.as_micros()),
                    phases.prepare.as_micros(),
                    phases.validate_ids.as_micros(),
                    phases.decode.as_micros(),
                    phases.heap_edit.as_micros(),
                    phases.index_edit.as_micros(),
                    phases.compare.as_micros(),
                    phases.page_gather.as_micros(),
                    phases.page_seal.as_micros(),
                    phases.page_verify.as_micros(),
                    phases.apply.as_micros(),
                    phases.apply.as_micros().saturating_sub(
                        phases.validate_ids.as_micros()
                            + phases.decode.as_micros()
                            + phases.heap_edit.as_micros()
                            + phases.index_edit.as_micros()
                            + phases.compare.as_micros()
                            + phases.page_gather.as_micros()
                    ),
                    phases.wal_encode.as_micros(),
                    phases.wal_write.as_micros(),
                    phases.wal_sync.as_micros(),
                    phases.db_write.as_micros(),
                    phases.db_sync.as_micros(),
                    phases.wal_clear.as_micros(),
                    phases.presence_build.as_micros(),
                    mutation_checksum(&mut db),
                    phases.wal_bytes,
                    phases.frames,
                    phases.heap_pages,
                    phases.index_pages,
                    phases.other_pages,
                    phases.descents,
                    phases.leaf_decodes,
                    phases.bulk_spans,
                    phases.indexes_updated,
                    phases.pages_allocated,
                    phases.pages_freed,
                    phases.ancestor_reads,
                    phases.ancestor_writes,
                    note.as_ref().map(|item| item.probe_us).unwrap_or(0),
                    note.as_ref().map(|item| item.validate_us).unwrap_or(0),
                    note.as_ref().map(|item| item.filter_us).unwrap_or(0),
                    note.as_ref().map(|item| item.discover_us).unwrap_or(0),
                    note.as_ref().map(|item| item.candidates).unwrap_or(0),
                    note.as_ref().map(|item| item.examined).unwrap_or(0),
                    note.as_ref().map(|item| item.heap_rows).unwrap_or(0),
                    note.as_ref().map(|item| item.modified).unwrap_or(0)
                );
                walls.push(wall);
            }
        }
        let mut sorted = walls.clone();
        sorted.sort_unstable();
        println!(
            "milestone39 median kind={kind} rows={rows} samples={} median_us={} min_us={} max_us={}",
            walls.len(),
            median(&walls),
            sorted.first().copied().unwrap_or(0),
            sorted.last().copied().unwrap_or(0)
        );
    }

    fn milestone39_gap(wall: u128, phases: &crate::storage::Profile) -> (u128, i128) {
        let plan = phases.plan.as_micros();
        let undo = phases.undo.as_micros();
        let memory_rest = phases
            .memory
            .as_micros()
            .saturating_sub(plan)
            .saturating_sub(undo);
        let nested = phases.validate_ids.as_micros()
            + phases.decode.as_micros()
            + phases.heap_edit.as_micros()
            + phases.index_edit.as_micros()
            + phases.compare.as_micros()
            + phases.page_gather.as_micros();
        let apply_rest = phases.apply.as_micros().saturating_sub(nested);
        let exclusive = phases.parse.as_micros()
            + plan
            + undo
            + memory_rest
            + phases.prepare.as_micros()
            + nested
            + apply_rest
            + phases.wal_encode.as_micros()
            + phases.wal_write.as_micros()
            + phases.wal_sync.as_micros()
            + phases.db_write.as_micros()
            + phases.db_sync.as_micros()
            + phases.wal_clear.as_micros();
        (exclusive, wall as i128 - exclusive as i128)
    }

    fn milestone39_sql(kind: &str, rows: i64) -> String {
        match kind {
            "one" => "DELETE FROM users WHERE id = 1;".to_string(),
            "ten" => "DELETE FROM users WHERE id >= 1 AND id <= 10;".to_string(),
            "buckets" => "DELETE FROM users WHERE bucket = 0 OR bucket = 1;".to_string(),
            "half" => format!("DELETE FROM users WHERE id < {};", rows / 2),
            "alternating" => "DELETE FROM users WHERE active = TRUE;".to_string(),
            "consecutive" => format!(
                "DELETE FROM users WHERE id >= 1 AND id < {};",
                (rows / 4).max(1)
            ),
            "sparse" => "DELETE FROM users WHERE bucket IS NULL;".to_string(),
            "all" => "DELETE FROM users WHERE TRUE OR id = 0;".to_string(),
            "wide" => format!("DELETE FROM users WHERE name = '{}';", "w".repeat(80)),
            "select-index" => "SELECT id, name FROM users WHERE id = 1;".to_string(),
            "select-scan" => "SELECT id, name FROM users WHERE active = TRUE;".to_string(),
            "update-index" => "UPDATE users SET name = 'edited' WHERE id = 1;".to_string(),
            "update-scan" => "UPDATE users SET name = 'edited' WHERE active = TRUE;".to_string(),
            "insert-one" => format!("INSERT INTO users VALUES ({}, 'new', TRUE, 1);", rows + 1),
            "insert-batch" => {
                let mut sql = String::from("INSERT INTO users VALUES ");
                for offset in 1..=32 {
                    if offset > 1 {
                        sql.push(',');
                    }
                    let id = rows + offset;
                    sql.push_str(&format!("({id}, 'batch', TRUE, 1)"));
                }
                sql.push(';');
                sql
            }
            "join" => "SELECT users.id, labels.tag FROM users JOIN labels ON users.bucket = labels.bucket;".to_string(),
            "group" => "SELECT bucket, COUNT(*) FROM users GROUP BY bucket;".to_string(),
            _ => unreachable!(),
        }
    }

    #[test]
    fn table_crc_matches_bitwise_crc_and_keeps_recovery() {
        let (_dir, base) = seed_delete_db("m42-agree", 300, 0x4200);
        let wide = "w".repeat(80);
        let statements = [
            "INSERT INTO users VALUES (301, 'added', TRUE, 1);".to_string(),
            "SELECT id, name FROM users WHERE id = 1;".to_string(),
            "UPDATE users SET name = 'edited' WHERE id = 2;".to_string(),
            "UPDATE users SET name = 'edited' WHERE active = TRUE;".to_string(),
            "DELETE FROM users WHERE id = 1;".to_string(),
            "DELETE FROM users WHERE bucket = 0 OR bucket = 1;".to_string(),
            "DELETE FROM users WHERE id < 150;".to_string(),
            "DELETE FROM users WHERE TRUE OR id = 0;".to_string(),
            format!("DELETE FROM users WHERE name = '{wide}';"),
        ];
        for sql in &statements {
            let (_fast_dir, fast_path, mut fast) = open_copy(&base, "m42-fast");
            let (_slow_dir, slow_path, mut slow) = open_copy(&base, "m42-slow");
            let fast_result = fast.execute(sql).unwrap();
            let slow_result = {
                let _guard = crate::storage::ForceBitwiseCrc::new();
                slow.execute(sql).unwrap()
            };
            assert_eq!(fast_result, slow_result, "{sql}");
            assert_eq!(
                fast.table("users").unwrap().row_ids(),
                slow.table("users").unwrap().row_ids(),
                "{sql}"
            );
            assert_eq!(
                fast.table("users").unwrap().next_row_id(),
                slow.table("users").unwrap().next_row_id(),
                "{sql}"
            );
            assert_eq!(table_rows(&mut fast), table_rows(&mut slow), "{sql}");
            assert_eq!(
                index_postings(&mut fast, "idx_users_id"),
                index_postings(&mut slow, "idx_users_id"),
                "{sql}"
            );
            assert_eq!(
                index_postings(&mut fast, "idx_users_bucket"),
                index_postings(&mut slow, "idx_users_bucket"),
                "{sql}"
            );
            assert_eq!(db_file(&fast_path), db_file(&slow_path), "{sql}");
            drop(fast);
            drop(slow);
            let mut again = Database::open(&fast_path).unwrap();
            let mut slow_open = Database::open(&slow_path).unwrap();
            assert_eq!(table_rows(&mut again), table_rows(&mut slow_open), "{sql}");
            assert_eq!(db_file(&fast_path), db_file(&slow_path), "{sql}");
        }
        let delete_sql = "DELETE FROM users WHERE bucket = 0 OR bucket = 1;";
        let wal_of = |label: &str, bitwise: bool| -> Vec<u8> {
            let (_dir, path, mut db) = open_copy(&base, label);
            db.set_inject(crate::storage::Inject::AfterLogSync);
            let error = if bitwise {
                let _guard = crate::storage::ForceBitwiseCrc::new();
                db.execute(delete_sql)
            } else {
                db.execute(delete_sql)
            };
            assert!(error.is_err(), "{label}");
            wal_bytes(&path)
        };
        assert_eq!(wal_of("m42-wal-fast", false), wal_of("m42-wal-slow", true));
        assert_precommit(
            &base,
            "m42-pre",
            delete_sql,
            crate::storage::Inject::BeforeLogSync,
        );
        for inject in [
            crate::storage::Inject::AfterLogSync,
            crate::storage::Inject::CommitSyncFailed,
            crate::storage::Inject::DuringCheckpoint(1),
        ] {
            assert_postcommit(&base, &format!("m42-post-{inject:?}"), delete_sql, inject);
        }
        {
            let _guard = crate::storage::ForceBitwiseCrc::new();
            assert_precommit(
                &base,
                "m42-pre-bit",
                delete_sql,
                crate::storage::Inject::BeforeLogSync,
            );
            for inject in [
                crate::storage::Inject::AfterLogSync,
                crate::storage::Inject::CommitSyncFailed,
                crate::storage::Inject::DuringCheckpoint(1),
            ] {
                assert_postcommit(&base, &format!("m42-bit-{inject:?}"), delete_sql, inject);
            }
        }
    }

